import {nearestRoad,roads,projectRoad} from './roads.js';
import {BEACH} from './beach-layout.js';
export function reserveParking(engine,incident,engines){if(engine.kind==='VPL'&&incident.waterRescue)return{target:[120,-161.1],entry:[128,-157.1],approach:[123,-161.1],exit:[112,-157.1],yaw:-Math.PI/2};const occupied=engines.filter(e=>e!==engine&&e.parking).map(e=>e.parking.target);if(incident.waterRescue||incident.setting==='beach'){const slot=BEACH.parking.find(p=>!occupied.some(q=>Math.hypot(q[0]-p.target[0],q[1]-p.target[1])<9));if(slot)return Object.fromEntries(Object.entries(slot).map(([k,v])=>[k,Array.isArray(v)?v.slice():v]));}const candidates=roads.filter(r=>!r.name.includes('(simulation)')&&(!r.trail||incident.requires==='CCF')).sort((a,b)=>Math.hypot(...projectRoad(incident.accessTarget||incident.target,a).map((v,i)=>v-(incident.accessTarget||incident.target)[i]))-Math.hypot(...projectRoad(incident.accessTarget||incident.target,b).map((v,i)=>v-(incident.accessTarget||incident.target)[i])));for(const road of candidates){const dx=road.b[0]-road.a[0],dz=road.b[1]-road.a[1],len=Math.hypot(dx,dz);if(len<28)continue;const dir=[dx/len,dz/len],laneWidth=road.express?5:2.1,shoulder=laneWidth+4;for(let d=20;d<len-18;d+=22)for(const side of[-1,1]){const center=[road.a[0]+dir[0]*d,road.a[1]+dir[1]*d],target=[center[0]+dir[1]*side*shoulder,center[1]-dir[0]*side*shoulder];if(occupied.some(p=>Math.hypot(p[0]-target[0],p[1]-target[1])<20))continue;const heading=[-side*dir[0],-side*dir[1]],lane=[center[0]+dir[1]*side*laneWidth,center[1]-dir[0]*side*laneWidth];return{target,entry:[lane[0]-heading[0]*8,lane[1]-heading[1]*8],approach:[target[0]-heading[0]*3,target[1]-heading[1]*3],exit:[lane[0]+heading[0]*8,lane[1]+heading[1]*8],yaw:Math.atan2(heading[0],heading[1])};}}throw new Error('Aucun emplacement disponible.');}
